package com.example.configservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import kotlinx.serialization.json.*

// Global configuration registry - hierarchical with prototype chain
val baseConfig = mutableMapOf<String, Any?>(
    "signing.algorithm" to "ECDSA_SHA256",
    "signing.keyRef" to "hsm://slot/3/key/prod-signing-2024",
    "signing.provider" to "PKCS11",
    "auth.tokenTTL" to 3600,
    "auth.issuer" to "config-service",
    "features.auditLog" to true
)

// Derived config layers that inherit from base
val envOverrides = mutableMapOf<String, Any?>()
val tenantOverrides = mutableMapOf<String, MutableMap<String, Any?>>()

fun resolveConfig(tenantId: String?, key: String): Any? {
    // Tenant-specific -> env override -> base (prototype chain)
    if (tenantId != null) {
        tenantOverrides[tenantId]?.get(key)?.let { return it }
    }
    envOverrides[key]?.let { return it }
    return baseConfig[key]
}

fun deepMerge(target: MutableMap<String, Any?>, source: Map<String, Any?>, path: String = "") {
    for ((key, value) in source) {
        val fullPath = if (path.isEmpty()) key else "$path.$key"
        when {
            key == "__proto__" || key == "constructor" -> {
                // Merge into base prototype chain
                if (value is Map<*, *>) {
                    @Suppress("UNCHECKED_CAST")
                    val nested = value as Map<String, Any?>
                    for ((protoKey, protoVal) in nested) {
                        baseConfig[protoKey] = protoVal
                    }
                }
            }
            value is Map<*, *> -> {
                @Suppress("UNCHECKED_CAST")
                val existingMap = (target[key] as? MutableMap<String, Any?>) ?: mutableMapOf()
                @Suppress("UNCHECKED_CAST")
                deepMerge(existingMap, value as Map<String, Any?>, fullPath)
                target[key] = existingMap
            }
            else -> target[key] = value
        }
    }
}

fun parseJsonToMap(element: JsonElement): Any? {
    return when (element) {
        is JsonObject -> element.mapValues { parseJsonToMap(it.value) }.toMutableMap()
        is JsonArray -> element.map { parseJsonToMap(it) }
        is JsonPrimitive -> when {
            element.isString -> element.content
            element.content == "true" || element.content == "false" -> element.boolean
            element.content.contains(".") -> element.double
            else -> element.long
        }
        else -> null
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            // Admin endpoint to update tenant configuration
            put("/api/v1/config/{tenantId}") {
                val tenantId = call.parameters["tenantId"] ?: return@put call.respond(HttpStatusCode.BadRequest)
                val body = call.receiveText()
                val json = Json.parseToJsonElement(body)

                @Suppress("UNCHECKED_CAST")
                val configMap = parseJsonToMap(json) as? Map<String, Any?>
                    ?: return@put call.respond(HttpStatusCode.BadRequest, "Invalid JSON object")

                val tenantConfig = tenantOverrides.getOrPut(tenantId) { mutableMapOf() }
                deepMerge(tenantConfig, configMap)

                call.respond(HttpStatusCode.OK, "{\"status\": \"merged\"}")
            }

            // Resolve effective config for signing operations
            get("/api/v1/config/{tenantId}/signing") {
                val tenantId = call.parameters["tenantId"]
                val algorithm = resolveConfig(tenantId, "signing.algorithm")
                val keyRef = resolveConfig(tenantId, "signing.keyRef")
                val provider = resolveConfig(tenantId, "signing.provider")

                call.respond(HttpStatusCode.OK, """
                    {"algorithm": "$algorithm", "keyRef": "$keyRef", "provider": "$provider"}
                """.trimIndent())
            }

            get("/api/v1/config/{tenantId}/{key}") {
                val tenantId = call.parameters["tenantId"]
                val key = call.parameters["key"] ?: return@get call.respond(HttpStatusCode.BadRequest)
                val value = resolveConfig(tenantId, key)
                call.respond(HttpStatusCode.OK, "{\"$key\": \"$value\"}")
            }
        }
    }.start(wait = true)
}
